CREATE OR REPLACE FUNCTION export_private.core_profile_page_v1(v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j export_private.core_jobs_v1;l uuid;g integer;item jsonb;page jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN';end if;
 if notification_private.exact(v,array['requestId','leaseId','generation','section','cursor','limit']) is not true
  or notification_private.uuid(v->'requestId') is not true or notification_private.uuid(v->'leaseId') is not true
  or export_private.profile_natural_v1(v->'generation',3) is not true or v->'generation'='0'
  or v->>'section' is distinct from 'snapshot' or v->'cursor' is distinct from 'null'::jsonb
  or export_private.profile_natural_v1(v->'limit',100) is not true or v->'limit'='0' then raise exception 'INVALID_INPUT';end if;
 l:=(v->>'leaseId')::uuid;g:=(v->>'generation')::integer;
 j:=export_private.lock_job_v1((v->>'requestId')::uuid,true);
 if j.request_id is null or export_private.live_lease_v1(j,l,g) is not true then return jsonb_build_object('kind','unavailable');end if;
 if (v->>'limit')::integer>(j.policy_snapshot->>'page_size')::integer then raise exception 'INVALID_INPUT';end if;
 item:=export_private.profile_source_v1(j.owner_id,j.request_id);
 page:=jsonb_build_object('schemaVersion','profile-core-export/1','section','snapshot','sourceDigest',notification_private.hash(jsonb_build_object('snapshot',jsonb_build_array(item))),
  'items',jsonb_build_array(item),'hasMore',false,'nextCursor',null,'sectionComplete',true);
 if octet_length(notification_private.canonical(page))>1000000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
 -- All original absolute lease clocks are checked again after source locks/read.
 if export_private.live_lease_v1(j,l,g) is not true then return jsonb_build_object('kind','unavailable');end if;
 return page;
end$function$
;
CREATE OR REPLACE FUNCTION export_private.profile_commit_qualifies_v1(j export_private.core_jobs_v1, modules jsonb, l uuid, g integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare m jsonb;item jsonb;begin
 if export_private.valid_modules_v1(modules,(j.policy_snapshot->>'max_pages')::integer) is not true then return false;end if;
 m:=modules->3;
 if m->'pages'='0' and m->'rows'='0' then return m->>'status' in('unavailable','failed','partial') and m->>'reason' in('HANDLER_MISSING','SOURCE_UNAVAILABLE','BOUNDED_LIMIT');end if;
 if m->>'status' is distinct from 'complete' or m->>'reason' is distinct from 'NONE' or m->'pages' is distinct from '1'::jsonb or m->'rows' is distinct from '1'::jsonb then return false;end if;
 if export_private.live_lease_v1(j,l,g) is not true then return false;end if;
 item:=export_private.profile_source_v1(j.owner_id,j.request_id);
 return notification_private.hash(jsonb_build_object('snapshot',jsonb_build_array(item)))=m->>'digest' and export_private.live_lease_v1(j,l,g);
exception when lock_not_available then return false;end$function$
;
CREATE OR REPLACE FUNCTION export_private.record_profile_provenance_v1(committed export_private.core_jobs_v1, lease_deadline timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j export_private.core_jobs_v1;a export_private.core_artifacts_v1;item jsonb;m jsonb;begin
 select * into j from export_private.core_jobs_v1 where request_id=committed.request_id for update nowait;
 if not found or to_jsonb(j) is distinct from to_jsonb(committed) or j.state not in('ready_partial','ready_complete')
  or export_private.valid_modules_v1(j.modules,(j.policy_snapshot->>'max_pages')::integer) is not true then raise exception 'INVALID_OUTPUT';end if;
 m:=j.modules->3;
 if m->'pages'='0' and m->'rows'='0' then
  if exists(select 1 from export_private.profile_snapshot_provenance_v1 where request_id=j.request_id and generation=j.generation) then raise exception 'INVALID_OUTPUT';end if;return;
 end if;
 -- This path may insert only after the actual original atomic artifact/job writes.
 -- Exact commit replay never calls this function or reconstructs a missing proof.
 if exists(select 1 from export_private.profile_snapshot_provenance_v1 where request_id=j.request_id and generation=j.generation) then raise exception 'INVALID_OUTPUT';end if;
 item:=export_private.profile_source_v1(j.owner_id,j.request_id);
 if m->>'status' is distinct from 'complete' or m->>'reason' is distinct from 'NONE' or m->'pages' is distinct from '1'::jsonb or m->'rows' is distinct from '1'::jsonb
  or m->>'digest' is distinct from notification_private.hash(jsonb_build_object('snapshot',jsonb_build_array(item))) then raise exception 'INVALID_OUTPUT';end if;
 select * into a from export_private.core_artifacts_v1 where request_id=j.request_id for share nowait;
 if not found then raise exception 'INVALID_OUTPUT';end if;
 if lease_deadline is null or lease_deadline<=clock_timestamp() or j.expires_at<=clock_timestamp() or j.artifact_expires_at<=clock_timestamp() or (j.policy_snapshot->>'valid_until')::timestamptz<=clock_timestamp() then raise exception 'INVALID_OUTPUT';end if;
 insert into export_private.profile_snapshot_provenance_v1 values(j.request_id,j.generation,j.owner_id,j.session_id,j.session_epoch,j.committed_lease,m->>'digest',
  (item->'watermark'->>'profileRevision')::bigint,(item->'watermark'->>'paceRevision')::bigint,(item->'watermark'->>'profileErasureFloor')::bigint,(item->'watermark'->>'paceErasureFloor')::bigint,
  (item->'sourceRows'->>'profiles')::integer,(item->'sourceRows'->>'watermarks')::integer,(item->'sourceRows'->>'operations')::integer,
  j.artifact_digest,j.artifact_bytes,j.commit_digest,j.completed_at,j.artifact_expires_at,a.key_id);
 if export_private.profile_managed_copy_v1(j.request_id,j.owner_id) is not true or lease_deadline<=clock_timestamp() then raise exception 'INVALID_OUTPUT';end if;
 perform journey_measurement_private.record_core_copy_v1(j,item);
end$function$
;
CREATE OR REPLACE FUNCTION export_private.profile_source_current_v1(j export_private.core_jobs_v1)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare m jsonb;item jsonb;p export_private.profile_snapshot_provenance_v1;begin
 if j.modules='[]' then return not exists(select 1 from export_private.profile_snapshot_provenance_v1 where request_id=j.request_id and generation=j.generation);end if;
 if export_private.valid_modules_v1(j.modules,(j.policy_snapshot->>'max_pages')::integer) is not true then return false;end if;
 m:=j.modules->3;
 if m->'pages'='0' and m->'rows'='0' then return not exists(select 1 from export_private.profile_snapshot_provenance_v1 where request_id=j.request_id and generation=j.generation);end if;
 -- D2 order: job -> watermark -> Profile -> ordered operations -> provenance.
 item:=export_private.profile_source_v1(j.owner_id,j.request_id);
 if export_private.profile_managed_copy_v1(j.request_id,j.owner_id) is not true then return false;end if;
 select * into p from export_private.profile_snapshot_provenance_v1 where request_id=j.request_id and generation=j.generation for share nowait;
 return notification_private.hash(jsonb_build_object('snapshot',jsonb_build_array(item)))=p.source_digest
  and (item->'sourceRows'-'measurement')=jsonb_build_object('profiles',p.source_profile_rows,'watermarks',p.source_watermark_rows,'operations',p.source_operation_rows)
  and (item->'watermark'->>'profileRevision')::bigint is not distinct from p.profile_revision
  and (item->'watermark'->>'paceRevision')::bigint is not distinct from p.pace_revision
  and (item->'watermark'->>'profileErasureFloor')::bigint is not distinct from p.profile_floor
  and (item->'watermark'->>'paceErasureFloor')::bigint is not distinct from p.pace_floor;
exception when lock_not_available then return false;end$function$
;
CREATE OR REPLACE FUNCTION export_private.profile_hooks_valid_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
