 for r in select key,value#>>'{}' digest from jsonb_each('{"notification_private.hash(jsonb)":"56d037a72a2869b2a5a9fc529d7f4f65","notification_private.uuid(jsonb)":"807ab1cc00b54bb5318e4e9166c80d1c","profile_data_private.sources_v1()":"8b91f04b63b4957b6894fbce1e1fa3f8","notification_private.canonical(jsonb)":"d64328eb0b38e8af0414c32ed690af90","export_private.profile_source_v1(uuid)":"9c8e2536d5d16a026303f4de1441962a","profile_data_private.inventory_v1(uuid)":"b7d92626b8d2076e4f8285e06e8e48ca","export_private.lock_job_v1(uuid,boolean)":"10fbb56d34cd46bbc605efd1a91a01b8","notification_private.exact(jsonb,text[])":"0efb90311270494f2df2ebdaf81a3bc1","public.privacy_core_export_v1(text,jsonb)":"910a4e990f59e0f385c6afa9aa5e370c","export_private.core_profile_page_v1(jsonb)":"c4db79e2d5c6a1933096064158d6e714","export_private.profile_ids_v1(jsonb,integer)":"d868816850af0affc3233f6cd681f9b5","export_private.profile_copies_valid_v1(jsonb)":"5d95d5e293a56216314dbc8935adb2ae","export_private.profile_summary_valid_v1(jsonb)":"731b398085cb2f6de2da8d16dad50060","export_private.valid_modules_v1(jsonb,integer)":"a012fc7607e819051c4b83867b4e4ad4","export_private.profile_integer_v1(jsonb,bigint)":"114575989f2ce7b0eb7b350514f2f86d","export_private.profile_natural_v1(jsonb,bigint)":"4f91a39b4198c9f7b9b8778bf1f95561","export_private.profile_row_valid_v1(jsonb,uuid)":"847b8f7f39004426cc4668734e02be58","export_private.profile_conflicts_valid_v1(jsonb)":"34875bab4b6c05c2f261ee53e21c0716","export_private.profile_provenance_immutable_v1()":"bc691ef7f0df72ff9d3bbf338fb65401","export_private.profile_managed_copy_v1(uuid,uuid)":"ac28e7dfeda5a9f101a55c887c946019","export_private.profile_normalize_integers_v1(jsonb)":"2b4badb49c04be45044bc69b92bbc194","profile_data_private.profile_v1(public.user_profiles)":"3e1055c61a20408bee0e2ec59b876b13","export_private.profile_operation_valid_v1(jsonb,uuid,bigint)":"9e450fb166ff6a84f64fda59811c49a6","export_private.profile_source_current_v1(export_private.core_jobs_v1)":"544fcfc5e46314ec6227a3f832d31ec5","export_private.live_lease_v1(export_private.core_jobs_v1,uuid,integer)":"10646bcc81751f81d1d0eaa994e26f43","profile_data_private.operation_row_v1(profile_data_private.operations_v1)":"442d85cb715f67c9376228407e0b2c8c","export_private.profile_decision_valid_v1(jsonb,text,bigint,bigint,bigint,integer)":"702505b2b62ef7945c5bf9962a4aaf25","profile_data_private.summary_v1(public.user_profiles,profile_data_private.watermarks_v1)":"b3f86bebba4fd3596933639c1c9cdebc","export_private.profile_commit_qualifies_v1(export_private.core_jobs_v1,jsonb,uuid,integer)":"5bff46eb72a7611c8780c509a3c89c59","export_private.record_profile_provenance_v1(export_private.core_jobs_v1,timestamp with time zone)":"474509af44e673b5cb73d1ade9500bea","export_private.profile_source_v1(uuid,uuid)":"de2e21ca5d20f0fa92b6df14e1089d4b","journey_measurement_private.module_supported_v1()":"86c2a06611322e3e22493830cb502521"}'::jsonb) loop
  if to_regprocedure(r.key) is null then return false;end if;
  select * into p from pg_proc where oid=r.key::regprocedure;
  if md5(pg_get_functiondef(p.oid)) is distinct from r.digest then return false;end if;
 end loop;
 return true;
end$function$
;
CREATE OR REPLACE FUNCTION conversation_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s record;actual_n text[];pk_n text[];foreign_n jsonb;column_specs jsonb;
begin
 if not turn_private.directions_schema_members_v1() then return false;end if;
 for s in select * from conversation_data_private.sources_v1() loop
  if to_regclass(s.relation_name) is null then return false;end if;
  select array_agg(attname::text order by attnum) into actual_n from pg_attribute where attrelid=s.relation_name::regclass and attnum>0 and not attisdropped;
  if actual_n is distinct from s.columns_n then return false;end if;
  select array_agg(a.attname::text order by key.ordinality) into pk_n from pg_constraint c
   cross join lateral unnest(c.conkey) with ordinality key(attnum,ordinality)
   join pg_attribute a on a.attrelid=c.conrelid and a.attnum=key.attnum where c.conrelid=s.relation_name::regclass and c.contype='p';
  if pk_n is distinct from s.pk then return false;end if;
 end loop;
 select jsonb_object_agg(relation_name,cols) into column_specs from (
  select source_spec.relation_name,jsonb_agg(jsonb_build_object('name',a.attname,'type',a.atttypid::regtype::text,'notNull',a.attnotnull) order by a.attnum) cols
  from conversation_data_private.sources_v1() source_spec join pg_attribute a on a.attrelid=source_spec.relation_name::regclass
  where a.attnum>0 and not a.attisdropped group by source_spec.relation_name
 ) metadata;
 if column_specs is distinct from '{"public.chat_threads":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"trip_id","type":"uuid","notNull":false},{"name":"status","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true}],"public.chat_turn_events":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"event_id","type":"text","notNull":true},{"name":"sequence","type":"integer","notNull":true},{"name":"schema_version","type":"text","notNull":true},{"name":"event_type","type":"text","notNull":true},{"name":"state","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.chat_turn_idempotency":[{"name":"owner_id","type":"uuid","notNull":true},{"name":"thread_id","type":"uuid","notNull":true},{"name":"idempotency_key","type":"text","notNull":true},{"name":"digest","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.memory_consumer_receipts":[{"name":"id","type":"uuid","notNull":true},{"name":"owner_id","type":"uuid","notNull":true},{"name":"memory_id","type":"uuid","notNull":true},{"name":"source_receipt_id","type":"uuid","notNull":true},{"name":"consumer_kind","type":"text","notNull":true},{"name":"turn_id","type":"uuid","notNull":false},{"name":"proposal_id","type":"uuid","notNull":false},{"name":"constraint_kind","type":"text","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true}],"public.model_budget_attempts":[{"name":"scope_id","type":"uuid","notNull":true},{"name":"attempt_id","type":"uuid","notNull":true},{"name":"task_id","type":"uuid","notNull":true},{"name":"provid