CREATE OR REPLACE FUNCTION profile_data_private.schema_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;actual jsonb;expected jsonb;fk jsonb;names text[]:=array['public.user_profiles','turn_private.assistant_directions_intakes_v1','turn_private.directions_operations_v1','turn_private.directions_result_sources_v1'];begin
 if not turn_private.directions_schema_members_v1() then return false;end if;
 -- Exact approved full application delta; unknown unlinked application tables
 -- also fail closed. Managed namespace checks remain the original fixed helper.
 if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)<> '86ecb9b9a24e703d20f661a0d9236310ee49208026bd1b82e72023267bca3b83' then return false;end if;
 for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;
 expected:='{"public.turns":{"columns":[["id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",false],["status","text",true],["created_at","timestamp with time zone",true],["thread_id","uuid",false],["updated_at","timestamp with time zone",true]],"constraints":["UNIQUE (id, owner_id)","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((status = ANY (ARRAY[''accepted''::text, ''planning''::text, ''retrieving''::text, ''generating''::text, ''validating''::text, ''completed''::text, ''proposal_ready''::text, ''unavailable''::text, ''failed''::text, ''cancelled''::text])))","FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL"]},"turn_private.work":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["session_id","uuid",true],["state","text",true],["attempt","integer",true],["max_attempts","integer",true],["lease_ms","integer",true],["lease_token","uuid",false],["expires_at","timestamp with time zone",false],["created_at","timestamp with time zone",true],["execution_mode","text",true]],"constraints":["CHECK (((attempt >= 0) AND (attempt <= 5)))","CHECK (((state = ''leased''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))","CHECK (((state = ''leased''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))","CHECK ((execution_mode = ANY (ARRAY[''text''::text, ''planning_comparison_v1''::text, ''planning_intake_comparison_v2''::text, ''scoped_trip_edit_v1''::text, ''travel_directions_v1''::text])))","CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))","CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (turn_id)","CHECK ((state = ANY (ARRAY[''queued''::text, ''leased''::text, ''completed''::text, ''failed''::text, ''cancelled''::text, ''quarantined''::text])))","FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE"]},"public.user_profiles":{"columns":[["owner_id","uuid",true],["display_name","text",false],["travel_pace","text",true],["locale","text",true],["currency","text",true],["distance_unit","text",true],["temperature_unit","text",true],["default_departure_time","time without time zone",true],["created_at","timestamp with time zone",true],["updated_at","timestamp with time zone",true],["pace_revision","bigint",true],["pace_state","text",true],["pace_notice","text",false],["pace_operation","uuid",false],["pace_request","jsonb",false],["pace_undo","jsonb",false],["profile_revision","bigint",true],["profile_saved_fields","jsonb",true]],"constraints":["CHECK (((pace_state <> ALL (ARRAY[''explicit''::text, ''paused''::text])) OR (pace_notice IS NOT NULL)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text, ''EUR''::text, ''RUB''::text, ''SAR''::text])))","CHECK (((display_name IS NULL) OR ((char_length(display_name) >= 1) AND (char_length(display_name) <= 80))))","CHECK ((distance_unit = ANY (ARRAY[''kilometre''::text, ''mile''::text])))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","CHECK (((pace_notice IS NULL) OR (pace_notice = ''local-planning-cross-trip-v1''::text)))","CHECK (((pace_revision >= 0) AND (pace_revision <= ''9007199254740990''::bigint)))","CHECK ((pace_state = ANY (ARRAY[''unset''::text, ''explicit''::text, ''paused''::text, ''revoked''::text])))","PRIMARY KEY (owner_id)","CHECK (((profile_revision >= 0) AND (profile_revision <= ''9007199254740990''::bigint)))","CHECK ((temperature_unit = ANY (ARRAY[''celsius''::text, ''fahrenheit''::text])))","CHECK ((travel_pace = ANY (ARRAY[''relaxed''::text, ''balanced''::text, ''packed''::text])))"]},"public.privacy_requests":{"columns":[["id","uuid",true],["owner_id","uuid",true],["action","text",true],["scope_version","text",true],["status","text",true],["execution_state","text",true],["created_at","timestamp with time zone",true]],"constraints":["CHECK ((action = ANY (ARRAY[''export''::text, ''delete''::text])))","CHECK ((execution_state = ''not_started''::text))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((scope_version = ''all-user-data-v1''::text))","CHECK ((status = ''requested''::text))"]},"turn_private.text_content":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["thread_id","uuid",true],["policy_id","uuid",true],["consent_id","uuid",true],["locale","text",true],["input_text","text",true],["output_kind","text",false],["output_text","text",false],["hidden_at","timestamp with time zone",false],["created_at","timestamp with time zone",true]],"constraints":["CHECK ((turn_private.valid_text(input_text, 4000) AND ((output_text IS NULL) OR turn_private.valid_text(output_text, 8000))))","CHECK (((output_text IS NULL) = (output_kind IS NULL)))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","CHECK ((output_kind = ANY (ARRAY[''answered''::text, ''partial''::text, ''clarification''::text, ''blocked''::text, ''technical_failure''::text])))","PRIMARY KEY (turn_id)","FOREIGN KEY (policy_id) REFERENCES turn_private.text_policies(id)"]},"public.model_budget_scopes":{"columns":[["id","uuid",true],["owner_id","uuid",true],["currency","text",true],["limit_micros","bigint",true],["task_limit_micros","bigint",true],["task_attempt_limit","integer",true],["concurrency_limit","integer",true],["enabled","boolean",true],["frozen","boolean",true],["expires_at","timestamp with time zone",true],["created_at","timestamp with time zone",true]],"constraints":["CHECK (((task_limit_micros >= 1) AND (task_limit_micros <= limit_micros)))","CHECK (((concurrency_limit >= 1) AND (concurrency_limit <= 1000)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text])))","CHECK (((limit_micros >= 1) AND (limit_micros <= ''1000000000000''::bigint)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE RESTRICT","PRIMARY KEY (id)","CHECK (((task_attempt_limit >= 1) AND (task_attempt_limit <= 1000)))"]},"turn_private.service_tasks":{"columns":[["id","uuid",true],["owner_id","uuid",true],["thread_id","uuid",true],["goal_turn_id","uuid",true],["last_turn_id","uuid",true],["policy_id","uuid",true],["consent_id","uuid",true],["scope_version","integer",true],["expected_result","text",true],["goal_digest","text",true],["budget_scope_id","uuid",false],["created_at","timestamp with time zone",true],["capacity_enforced","boolean",true]],"constraints":["CHECK ((expected_result = ANY (ARRAY[''text_answer''::text, ''reviewed_answer''::text])))","CHECK ((goal_digest ~ ''^[a-f0-9]{64}$''::text))","FOREIGN KEY (goal_turn_id) REFERENCES turn_private.text_content(turn_id) DEFERRABLE INITIALLY DEFERRED","FOREIGN KEY (last_turn_id) REFERENCES turn_private.text_content(turn_id) DEFERRABLE INITIALLY DEFERRED","PRIMARY KEY (id)","FOREIGN KEY (policy_id) REFERENCES turn_private.text_policies(id)","CHECK ((scope_version = 1))","UNIQUE (thread_id)"]},"export_private.core_jobs_v1":{"columns":[["request_id","uuid",true],["owner_id","uuid",true],["session_id","uuid",true],["session_epoch","bigint",true],["scope","text",true],["policy_id","uuid",true],["policy_snapshot","jsonb",true],["state","text",true],["generation","integer",true],["lease_id","uuid",false],["lease_expires_at","timestamp with time zone",false],["claim_operation","uuid",false],["claim_digest","text",false],["committed_lease","uuid",false],["completed_at","timestamp with time zone",false],["modules","jsonb",true],["artifact_digest","text",false],["artifact_bytes","integer",false],["artifact_expires_at","timestamp with time zone",false],["created_at","timestamp with time zone",true],["expires_at","timestamp with time zone",true],["commit_digest","text",false],["memory_source_revision","bigint",false],["entitlement_source_revision","bigint",false],["pdf_export_version","text",false],["pdf_source_revision","bigint",false],["pdf_material_valid_until","timestamp with time zone",false],["directions_source_digest","text",false]],"constraints":["CHECK (((directions_source_digest IS NULL) OR (directions_source_digest ~ ''^[a-f0-9]{64}$''::text)))","CHECK (((entitlement_source_revision >= 1) AND (entitlement_source_revision <= ''9007199254740990''::bigint)))","CHECK (((generation >= 1) AND (generation <= 3)))","CHECK (((memory_source_revision >= 1) AND (memory_source_revision <= ''9007199254740990''::bigint)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (request_id)","FOREIGN KEY (policy_id) REFERENCES export_private.core_policies_v1(id)","FOREIGN KEY (request_id) REFERENCES public.privacy_requests(id) ON DELETE CASCADE","CHECK ((scope = ''core-export-d2/1''::text))","CHECK ((state = ANY (ARRAY[''queued''::text, ''running''::text, ''ready_partial''::text, ''ready_complete''::text, ''failed''::text, ''expired''::text])))"]},"recovery_private.lineage_v1":{"columns":[["proposal_id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",true],["context_id","uuid",true],["operation_id","uuid",true],["patch","jsonb",true],["proposal_digest","text",true]],"constraints":["FOREIGN KEY (context_id, owner_id, trip_id) REFERENCES recovery_private.contexts_v1(id, owner_id, trip_id) ON DELETE CASCADE","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","FOREIGN KEY (owner_id, operation_id) REFERENCES recovery_private.operations_v1(owner_id, operation_id) ON DELETE CASCADE","PRIMARY KEY (proposal_id)","FOREIGN KEY (proposal_id) REFERENCES public.trip_proposals(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE CASCADE"]},"scoped_edit_private.work_v1":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",true],["task_id","uuid",true],["operation_id","uuid",true],["context_id","uuid",true],["policy_id","uuid",true],["sc